target_by_number = {v['number']: (k, v) for k, v in refs['targets'].items()}
for number, assessments in checks.items():
    drafts[number]['reference_checks'] = [
        {'target_key': target_by_number[n][0], 'view_sha256': target_by_number[n][1]['view_sha256'], 'assessment': assessment}
        for n, assessment in assessments.items()
    ]

drafts['L211-2-1']['review_notes'] += " Nouveau renvoi explicite à L211-2-2 : cette cible ne figure pas comme cible dans reference-targets.json, mais sa source complète et sa proposition sont celles du présent lot ; elles portent bien le compte rendu annuel de gestion."

answer = [drafts[a['number']] for a in sources]
assert len(answer) == 24 and len(drafts) == 24
for a in answer:
    key = a['code_id'] + '|' + a['source_id']
    required = set(refs['requirements'][key])
    actual = {c['target_key'] for c in a.get('reference_checks', [])}
    assert required == actual, (a['number'], required - actual, actual - required)
    for c in a.get('reference_checks', []):
        assert c['view_sha256'] == refs['targets'][c['target_key']]['view_sha256']
        assert len(c['assessment']) >= 80
    source = next(s for s in sources if s['source_id'] == a['source_id'])
    assert all(a[k] == source[k] for k in ['code_id', 'source_id', 'source_sha256', 'number'])
    if source.get('benefit_check_required'):
        assert len(a.get('benefit_review', '')) >= 100
    for r in a.get('removed_provisions', []):
        assert len(r) >= 30
    assert a['status'] == 'rewrite_draft'

(ROOT / 'answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f"answer.json : {len(answer)} articles ; {sum(len(a.get('reference_checks', [])) for a in answer)} contrôles de renvois.")
